import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_AULA, MODELO_ESCUELA } from '../../models/escuela-aula.model.mjs';

export async function trasladarAulaRepository(aulaId, escuelaId) {
  const { Attributes } = await MODELO_AULA.build(EntityRepository).update(
    { aulaId, escuelaId },
    {
      condition: { attr: 'aulaId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { consultarEscuelaService } from './service.mjs';

export async function handler(event) {
  const escuelaId = Number(event.pathParameters.escuelaId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarEscuelaService(escuelaId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarEscuelaRepository, consultarEscuelaRepository } from './repository.mjs';

export async function consultarEscuelaService(escuelaId, minimo) {
  const escuela = await buscarEscuelaRepository(escuelaId);
  if (!escuela) throw new Error('Escuela no encontrado');
  const aulas = await consultarEscuelaRepository(escuelaId, minimo);
  return { escuela, aulas };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_AULA, MODELO_ESCUELA } from '../../models/escuela-aula.model.mjs';

export async function buscarEscuelaRepository(escuelaId) {
  const { Item } = await MODELO_ESCUELA.build(EntityRepository).get(
    { escuelaId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarEscuelaRepository(escuelaId, minimo) {
  const { Items = [] } = await MODELO_AULA.build(EntityRepository).query(
    { index: 'PorEscuela', partition: escuelaId },
    { filters: { Aula: { attr: 'capacidad', gte: minimo } } }
  );
  return Items;
}
